'use client'

import { HtmlPrototypePage } from '@/components/shared/HtmlPrototypePage'

const styles = ":root{--c-primary:#7B1533;--c-primary-dark:#6A1029;--c-primary-lt:#8f1a3a;--c-accent:#ADD036;--c-bg:#F5F5F5;--c-surface:#FFFFFF;--c-border:#E5E5EA;--c-text:#111111;--c-text2:#555555;--c-text3:#888888;--c-hint:#BBBBBB;}\n*,*::before,*::after{box-sizing:border-box;margin:0;padding:0;-webkit-font-smoothing:antialiased;}\nbody{background:#0a0a0a;min-height:100vh;font-family:\u0027Plus Jakarta Sans\u0027,-apple-system,sans-serif;font-size:14px;color:var(--c-text);}\n.page{width:100%;max-width:430px;margin:0 auto;min-height:100vh;background:var(--c-bg);overflow:hidden;}\n@media(min-width:500px){body{padding:40px 20px;display:flex;justify-content:center;align-items:flex-start;}.page{min-height:auto;border-radius:36px;border:8px solid #1a1a1a;box-shadow:0 32px 80px rgba(0,0,0,0.7);}}\n@media(min-width:1024px){body{align-items:center;padding:40px;min-height:100vh;}}\n.scroll{height:812px;overflow-y:auto;padding-bottom:40px;}.scroll::-webkit-scrollbar{display:none;}\n\n/* HERO */\n.hero{background:var(--c-primary);padding:40px 24px 0;display:flex;flex-direction:column;align-items:center;position:relative;overflow:hidden;}\n.hero::before{content:\u0027\u0027;position:absolute;top:-40px;right:-40px;width:200px;height:200px;background:rgba(255,255,255,0.03);border-radius:50%;}\n.logo-wrap{margin-bottom:20px;}\n.tagline{font-size:13px;color:rgba(255,255,255,0.55);text-align:center;margin-bottom:20px;}\n.mascot-wrap{width:100%;display:flex;justify-content:center;}\n.mascot-wrap img{width:75%;max-width:280px;object-fit:contain;margin-bottom:-4px;}\n\n/* STORY SECTION */\n.story{background:#fff;padding:36px 48px;border-bottom:1px solid #eee;}\n.story-text{font-size:13px;color:var(--c-text2);line-height:1.6;margin-bottom:28px;text-align:center;}\n.story-text strong{color:var(--c-text);font-weight:700;}\n.story-text br+br{display:none;}\n\n/* SIGNATURE */\n.signature-wrap{display:flex;flex-direction:column;align-items:flex-end;gap:4px;}\n\n.signature-title{font-size:11px;color:var(--c-text3);font-weight:500;}\n.signature-line{width:120px;height:1.5px;background:var(--c-border);margin-bottom:6px;}\n\n/* AMOUNT BUTTONS */\n.amount-section{background:#fff;padding:20px 24px;border-bottom:1px solid #eee;margin-top:1px;}\n.amount-label{font-size:13px;font-weight:700;color:var(--c-text);text-align:center;margin-bottom:14px;}\n.amount-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:14px;}\n.amount-btn{border:2px solid var(--c-border);border-radius:12px;padding:14px 8px;background:#fff;font-family:inherit;cursor:pointer;text-align:center;transition:all 0.15s;}\n.amount-btn.selected{border-color:var(--c-primary);background:#fff5f7;}\n.amount-price{font-size:18px;font-weight:800;color:var(--c-primary);}\n.amount-label-sm{font-size:10px;color:var(--c-hint);margin-top:3px;}\n.amount-btn.selected .amount-price{color:var(--c-primary);}\n\n/* QR SECTION */\n.qr-section{background:#fff;padding:24px;margin-top:1px;}\n.qr-title{font-size:14px;font-weight:700;color:var(--c-text);text-align:center;margin-bottom:6px;}\n.qr-sub{font-size:12px;color:var(--c-text3);text-align:center;margin-bottom:16px;line-height:1.6;}\n.qr-wrap{display:flex;justify-content:center;margin-bottom:14px;}\n.qr-img{width:220px;height:auto;border-radius:16px;box-shadow:0 4px 20px rgba(0,0,0,0.12);}\n.qr-hint{font-size:11px;color:var(--c-hint);text-align:center;line-height:1.6;}\n\n/* DOWNLOAD BTN */\n.dl-btn{width:100%;margin-top:14px;background:linear-gradient(180deg,#8f1a3a 0%,#6a1029 100%);border:none;border-radius:14px;padding:15px 20px;display:flex;align-items:center;justify-content:center;gap:10px;color:#fff;font-size:15px;font-weight:700;font-family:inherit;cursor:pointer;position:relative;overflow:hidden;box-shadow:0 1px 0 rgba(255,255,255,0.16) inset,0 -1px 0 rgba(0,0,0,0.2) inset,0 6px 20px rgba(123,21,51,0.45);transition:transform 0.12s;}\n.dl-btn::after{content:\u0027\u0027;position:absolute;top:0;left:0;right:0;height:50%;background:linear-gradient(180deg,rgba(255,255,255,0.12) 0%,transparent 100%);border-radius:14px 14px 0 0;pointer-events:none;}\n.dl-btn:active{transform:scale(0.985);}\n\n/* COUNTER */\n.counter-section{background:var(--c-primary);padding:16px 24px;margin-top:1px;display:flex;align-items:center;justify-content:center;gap:12px;}\n.counter-num{font-size:28px;font-weight:800;color:#fff;}\n.counter-text{font-size:12px;color:rgba(255,255,255,0.7);line-height:1.5;}\n\n/* DOAS */\n.doa-section{background:#fff;padding:20px 24px;margin-top:1px;text-align:center;}\n.doa-text{font-size:12px;color:var(--c-text3);line-height:1.6;font-style:italic;}\n.back-btn{width:32px;height:32px;border-radius:50%;background:rgba(255,255,255,0.15);border:none;display:flex;align-items:center;justify-content:center;cursor:pointer;flex-shrink:0;}"
